      "end_time_mmss": "01:26.599",
      "description_text": "Franz si unisce ai fratelli minori sorridendo amichevolmente."
    },
    {
      "start_time_mmss": "01:27.869",
      "end_time_mmss": "01:31.577",
      "description_text": "Il capitano della nave passeggia tranquillo."
